import type { Alignment, Element, Stats, UnitKind } from '../types';
import { baseAbility } from './abilities';

// The thirty Masters, generated by the Stat Budget generator
// (rules/statgen.ts, scripts/masters.run.ts) and kept here as fixed data.
// Every Side picks one before the match. All walk + wade, and each has one
// physical Ability (Strike, or a Shot or Lob for the five that attack at range);
// four have an Element and four an Alignment. Each spread sums to the Stat Budget: MP, which also sets Mana
// Income, trades against Speed, Move, the defences and (at range) ATK.
// After generation, some were adjusted by hand: spreads below the MDF floor
// (MDF_FLOOR) were raised to 3, paid for mostly with DEF (only Sylph keeps
// MDF 2), and hard hitters with little reach were compensated when ATK came
// to be priced by reach. ATK, DEF, MP and MDF are on the halved scale
// (Damage = ATK − DEF): the spreads were converted from the old scale, then
// nudged by a point or so to sit on the refitted budget.

type Def = [
  id: string,
  name: string,
  stats: [atk: number, def: number, mp: number, mdf: number, spd: number, mov: number],
  ability: string,
  element?: Element | null,
  alignment?: Alignment,
];
// The repo's balance overrides of the time are baked in, and Speed is on the
// scale shifted down by 6 (same delays).

const DEFS: Def[] = [
  ['corsair', 'Corsair', [9, 3, 7, 4, 4, 5], 'shot-3'],
  ['lancer', 'Lancer', [11, 5, 5, 6, 9, 4], 'shot-4'],
  ['harpist', 'Harpist', [9, 4, 7, 4, 5, 3], 'shot-4'],
  ['savage', 'Savage', [11, 7, 4, 6, 7, 5], 'shot-5'],
  ['tracker', 'Tracker', [8, 3, 6, 4, 8, 4], 'lob-6'],
  ['witch', 'Witch', [6, 2, 8, 3, 4, 4], 'strike'],
  ['sylph', 'Sylph', [5, 1, 7, 2, 8, 5], 'strike', 'air'],
  ['duelist', 'Duelist', [6, 1, 7, 3, 8, 3], 'strike'],
  ['valkyr', 'Valkyr', [12, 5, 6, 3, 7, 5], 'strike'],
  ['lich', 'Lich', [5, 2, 8, 5, 4, 3], 'strike'],
  ['seraph', 'Seraph', [9, 4, 6, 7, 7, 3], 'strike', null, 'day'],
  ['regent', 'Regent', [9, 3, 6, 5, 7, 6], 'strike'],
  ['warlock', 'Warlock', [9, 1, 7, 4, 6, 4], 'strike'],
  ['satyr', 'Satyr', [9, 2, 5, 4, 11, 5], 'strike'],
  ['efreet', 'Efreet', [10, 3, 6, 3, 9, 4], 'strike', 'fire'],
  ['templar', 'Templar', [11, 6, 6, 5, 6, 4], 'strike', null, 'day'],
  ['banshee', 'Banshee', [6, 1, 7, 5, 8, 3], 'strike', null, 'night'],
  ['ronin', 'Ronin', [11, 4, 6, 4, 10, 3], 'strike'],
  ['oni', 'Oni', [13, 6, 5, 4, 11, 4], 'strike'],
  ['vampire', 'Vampire', [9, 3, 7, 3, 6, 5], 'strike', null, 'night'],
  ['herald', 'Herald', [11, 5, 5, 5, 9, 5], 'strike'],
  ['oracle', 'Oracle', [5, 1, 7, 4, 6, 5], 'strike'],
  ['gorgon', 'Gorgon', [10, 5, 6, 6, 6, 5], 'strike'],
  ['naga', 'Naga', [7, 4, 7, 3, 6, 3], 'strike'],
  ['magus', 'Magus', [6, 1, 8, 3, 5, 3], 'strike'],
  ['shadow', 'Shadow', [7, 2, 6, 4, 10, 3], 'strike'],
  ['selkie', 'Selkie', [6, 2, 6, 5, 9, 5], 'strike', 'water'],
  ['lamia', 'Lamia', [9, 2, 7, 5, 6, 4], 'strike'],
  ['hermit', 'Hermit', [6, 4, 7, 5, 4, 4], 'strike'],
  ['dwarf', 'Dwarf', [12, 5, 6, 4, 8, 3], 'strike', 'earth'],
];

function build([id, name, s, ability, element, alignment]: Def): UnitKind {
  const stats: Stats = { atk: s[0], def: s[1], mp: s[2], mdf: s[3], spd: s[4], mov: s[5] };
  return {
    id,
    name,
    isMaster: true,
    element: element ?? null,
    alignment: alignment ?? 'none',
    cost: 0,
    stats,
    moveTypes: ['walk', 'wade'],
    ability: baseAbility(ability),
  };
}

/** Built-in Masters (before any balance overrides). */
export const BASE_MASTERS: readonly UnitKind[] = DEFS.map(build);

/** The default Master (Regent, an all-rounder). */
export const DEFAULT_MASTER = 'regent';
